static std::string tag_json(const std::string & gp, int64_t reasoning_on, int64_t parallel, int64_t required,
                            const std::string & pcs, const std::string & npx, const std::string & nsx,
                            const std::string & cidp = "", const std::string & cids = "", int64_t cid_pos = 2,
                            const std::string & ssec = "", const std::string & esec = "") {
    Arena a;
    std::vector<int64_t> noff{0, 11}, nlen{11, 8}, soff{0, 102}, slen{102, 33};
    auto g = vb(gp), rs = vb("<think>"), re = vb("</think>");
    auto p = vb(npx), s = vb(nsx), cl = vb(""), as = vb(""), ae = vb("");
    auto ss = vb(ssec), se = vb(esec), pc = vb(pcs), pe = vb("");
    auto cp = vb(cidp), cs = vb(cids);
    auto nm = vb(NAMES), sc = vb(SCHEMAS);
    int64_t root = autoparser_build_tag_json(bu(g), bu(rs), bu(re), reasoning_on, bu(p), bu(s), bu(cl),
        bu(as), bu(ae), bu(ss), bu(se), bu(pc), bu(pe), bu(cp), bu(cs), cidp.empty() ? 0 : cid_pos, 0,
        bu(nm), li(noff), li(nlen), bu(sc), li(soff), li(slen), 2, parallel, required,
        li(a.kind), li(a.cfirst), li(a.ccount), li(a.children), li(a.sidx), li(a.dstart),
        li(a.dcount), li(a.mn), li(a.mx), bu(a.pool), li(a.st));
    return dump_of(root, a);
}

static std::string tag_tagged(const std::string & gp, int64_t reasoning_on, const std::string & rs, const std::string & re,
                              const std::string & fnp, const std::string & ns, const std::string & fc,
                              const std::string & anp, const std::string & ans, const std::string & avp,
                              const std::string & avs, const std::string & ss, const std::string & se,
                              const std::string & pcs, const std::string & pce, int64_t tolerate,
                              int64_t parallel, int extra = 0,
                              const std::string & astart = "", const std::string & aend = "") {
    Arena a;
    std::vector<int64_t> noff = extra ? std::vector<int64_t>{0, 11, 19, 27} : std::vector<int64_t>{0, 11, 19};
    std::vector<int64_t> nlen = extra ? std::vector<int64_t>{11, 8, 8, 4} : std::vector<int64_t>{11, 8, 8};
    std::vector<int64_t> soff = extra ? std::vector<int64_t>{0, 102, 135, 168} : std::vector<int64_t>{0, 102, 135};
    std::vector<int64_t> slen = extra ? std::vector<int64_t>{102, 33, 33, 97} : std::vector<int64_t>{102, 33, 33};
    std::vector<int64_t> poff = extra ? std::vector<int64_t>{0, 4, 8, 13, 14} : std::vector<int64_t>{0, 4, 8};
    std::vector<int64_t> plen = extra ? std::vector<int64_t>{4, 4, 5, 1, 1} : std::vector<int64_t>{4, 4, 5};
    std::vector<int64_t> ptype = extra ? std::vector<int64_t>{1, 0, 1, 1, 0} : std::vector<int64_t>{1, 0, 1};
    std::vector<int64_t> preq = extra ? std::vector<int64_t>{1, 0, 0, 1, 1} : std::vector<int64_t>{1, 0, 0};
    std::vector<int64_t> pbase = extra ? std::vector<int64_t>{0, 2, 2, 3, 5} : std::vector<int64_t>{0, 2, 2};
    std::vector<int64_t> pcount = extra ? std::vector<int64_t>{2, 0, 1, 2, 0} : std::vector<int64_t>{2, 0, 1};
    auto g = vb(gp), r1 = vb(rs), r2 = vb(re), fp = vb(fnp), su = vb(ns), cl = vb(fc);
    auto an = vb(anp), asu = vb(ans), av = vb(avp), avsu = vb(avs);
    auto ast = vb(astart), aen = vb(aend), sst = vb(ss), sen = vb(se), pc = vb(pcs), pceb = vb(pce);
    auto cp = vb(""), cs = vb("");
    auto nm = vb(extra ? (NAMES + std::string("set_modeswap")) : NAMES);
    auto sc = vb(extra ? (SCHEMAS + std::string("{\"type\":\"object\",\"properties\":{}}")
        + std::string("{\"type\":\"object\",\"properties\":{\"a\":{\"type\":\"string\"},\"b\":{\"type\":\"number\"}},\"required\":[\"a\",\"b\"]}")) : SCHEMAS);
    auto pn = vb(extra ? (PARAM_NAMES + std::string("levelab")) : PARAM_NAMES);
    std::string PS = std::string(SCHEMAS) + "{\"type\":\"number\"}";
    auto psc = vb(PS);
    std::vector<int64_t> pso = extra ? std::vector<int64_t>{0, 135, 0, 0, 135} : std::vector<int64_t>{0, 135, 0};
    std::vector<int64_t> psl = extra ? std::vector<int64_t>{102, 17, 0, 0, 17} : std::vector<int64_t>{102, 17, 0};
    int64_t root = autoparser_build_tag_tagged(bu(g), bu(r1), bu(r2), reasoning_on,
        bu(fp), bu(su), bu(cl), bu(an), bu(asu), bu(av), bu(avsu), bu(ast), bu(aen),
        bu(sst), bu(sen), bu(pc), bu(pceb), bu(cp), bu(cs), 0, tolerate,
        bu(nm), li(noff), li(nlen), bu(sc), li(soff), li(slen),
        bu(pn), li(poff), li(plen), li(ptype), li(preq), li(pbase), li(pcount),
        bu(psc), li(pso), li(psl), extra ? 4 : 2, parallel, 0,
        li(a.kind), li(a.cfirst), li(a.ccount), li(a.children), li(a.sidx), li(a.dstart),
        li(a.dcount), li(a.mn), li(a.mx), bu(a.pool), li(a.st));
    return dump_of(root, a);
}

