static void check(int idx, const std::string & got) {
    ++cases; ++values;
    if (got != expected[idx]) {
        ++fails;
        printf("FAIL %s\n  got =[%s]\n  want=[%s]\n", names[idx], got.c_str(), expected[idx]);
    } else {
        printf("ok %s\n", names[idx]);
    }
}

